function normalizeProfileText(value: string): string {
  return value
    .normalize("NFD")
    .replace(/\p{Diacritic}/gu, "")
    .toLocaleLowerCase("sv-SE");
}

export function isPlumbingProfileText(value: string | null | undefined): boolean {
  if (!value) return false;
  const text = normalizeProfileText(value);
  return PLUMBING_KEYWORD_STEMS.some((stem) => text.includes(stem));
}

export function hasPlumbingProfile(args: {
  vertical?: Vertical | string | null;
  text?: string | null;
  services?: readonly string[] | null;
}): boolean {
  const vertical = args.vertical ?? "generic";
  if (vertical !== "handyman" && vertical !== "generic") return false;
  return isPlumbingProfileText(
    [args.text, ...(args.services ?? [])].filter(Boolean).join(" "),
  );
}

