function profileSuggestionsFor(
  text: string,
): { sv: string; en: string; pl: string }[] | undefined {
  const normalized = normalizeProfileText(text);
  return PROFILE_SUGGESTIONS.find(
    (p) => p.match?.test(normalized) || p.stems.some((stem) => normalized.includes(stem)),
  )?.suggestions;
}

function localizeSuggestions(
  suggestions: { sv: string; en: string; pl: string }[],
  locale: string,
): string[] {
  return suggestions.map((s) => (s as Record<string, string>)[locale] ?? s.en);
}

export function getServiceSuggestions(
  vertical: Vertical,
  locale: string,
): string[] {
  return localizeSuggestions(SERVICE_SUGGESTIONS[vertical], locale);
}

export function getServiceSuggestionsForProfile(
  vertical: Vertical,
  locale: string,
  profile?: { text?: string | null; services?: readonly string[] | null },
): string[] {
  if (
    hasPlumbingProfile({
      vertical,
      text: profile?.text,
      services: profile?.services,
    })
  ) {
    return localizeSuggestions(PLUMBING_SERVICE_SUGGESTIONS, locale);
  }
  // Craft-specific chips only where the fallback tables are generic; curated
  // verticals (dentist, restaurant, …) keep their own tables.
  if (vertical === "generic" || vertical === "freelancer") {
    const fromProfile = profileSuggestionsFor(
      [profile?.text, ...(profile?.services ?? [])].filter(Boolean).join(" "),
    );
    if (fromProfile) return localizeSuggestions(fromProfile, locale);
  }
  return localizeSuggestions(SERVICE_SUGGESTIONS[vertical], locale);
}
